/** 把数值夹在 [0, 1] 之间。 */
function clamp01(value: number) {
  if (!Number.isFinite(value)) return 0
  return Math.min(1, Math.max(0, value))
}

/**
 * 橡皮筋拉伸量：指针越过轨道边界 `distance` 像素时的视觉拉伸。
 * 曲线是饱和的（越拉越难拉），结果永远小于 `max`，所以轨道不会被拉得没边。
 */
function rubberBand(distance: number, max: number) {
  if (!Number.isFinite(max) || max <= 0 || distance <= 0) return 0
  return max * (1 - 1 / (1 + (0.55 * distance) / max))
}

/** 值在轨道内的百分比（0–100）。 */
function valueToPercent(value: number, min: number, max: number) {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(100, Math.max(0, ((value - min) / span) * 100))
}

/** step 的小数位数：1 → 0，0.5 → 1，0.05 → 2，用于读数与读屏文本。 */
function stepDecimals(step: number) {
  if (!Number.isFinite(step) || step <= 0) return 0
  const text = String(step)
  const exponential = text.split("e-")[1]
  if (exponential) return Math.min(6, Number(exponential))
  const dot = text.indexOf(".")
  return dot === -1 ? 0 : Math.min(6, text.length - dot - 1)
}

/** 单值 / 区间统一取成升序数组，区间时报文的顺序与 Base UI 一致。 */
function toNumberList(value: number | readonly number[]) {
  if (typeof value === "number") return [value]
  return [...value].sort((a, b) => a - b)
}

/**
 * 把 `ticks` 属性换算成刻度值数组（含两端）。
 * 数字表示等分段数，返回 n + 1 个值，其中 n - 1 个落在轨道内部；数组则原样排序、去重并夹在范围内。
 */
function resolveTicks(
  ticks: number | readonly number[] | undefined,
  min: number,
  max: number,
) {
  if (ticks === undefined) return []
  if (typeof ticks !== "number") {
    const list = ticks
      .filter((item) => Number.isFinite(item) && item >= min && item <= max)
      .sort((a, b) => a - b)
    return list.filter((item, index) => index === 0 || item !== list[index - 1])
  }
  const count = Math.floor(ticks)
  if (!Number.isFinite(count) || count < 2) return []
  return Array.from(
    { length: count + 1 },
    (_, index) => min + ((max - min) * index) / count,
  )
}

/** 离该值最近的刻度值；没有刻度时返回 undefined。 */
function nearestTick(value: number, ticks: readonly number[]) {
  let nearest: number | undefined
  let distance = Infinity
  for (const tick of ticks) {
    const next = Math.abs(tick - value)
    if (next < distance) {
      distance = next
      nearest = tick
    }
  }
  return nearest
}

/** 从 `from` 走到 `to` 的过程中是否越过了某个刻度（含 `to` 所在的刻度，不含 `from`）。 */
function crossedTick(from: number, to: number, ticks: readonly number[]) {
  const low = Math.min(from, to)
  const high = Math.max(from, to)
  return ticks.some((tick) => tick > low && tick <= high)
}

/**
 * 把值对齐到 `min + n * step` 并夹在 [min, max]，值不是有限数时返回 `undefined`。
 *
 * 浮点误差靠「搬到整数域再算」消除：按 min / step / value 三者里最多的小数位放大成整数，
 * 算出整数序号后再除回去，所以 0.1 这种二进制表示不精确的 step 也不会跑出 0.30000000000000004。
 * 上界直接用 `max`（与 Base UI 一致：即使 `max` 不在步长网格上，键盘与指针也能取到它）。
 *
 * 例：min=0.05 step=0.1 tick=0.15 → 0.15；min=2700 step=100 tick=3650 → 3700。
 */
function alignToStep(value: number, min: number, max: number, step: number) {
  if (!Number.isFinite(value)) return undefined
  const clamped = Math.min(max, Math.max(min, value))
  if (!Number.isFinite(step) || step <= 0) return clamped
  const decimals = Math.max(
    stepDecimals(min),
    stepDecimals(step),
    stepDecimals(clamped),
  )
  const factor = 10 ** decimals
  const minInt = Math.round(min * factor)
  const stepInt = Math.max(1, Math.round(step * factor))
  const valueInt = Math.round(clamped * factor)
  const alignedInt = minInt + Math.round((valueInt - minInt) / stepInt) * stepInt
  // 除法得到的是该十进制值最接近的 double，等价于字面量，不需要再 toFixed
  const aligned = alignedInt / factor
  return Math.min(max, Math.max(min, aligned))
}

type SnapToTicksOptions = {
  /** 吸附目标（含两端的刻度值） */
  ticks: readonly number[]
  min: number
  max: number
  /** 吸附后的值要对齐到 `min + n * step`，否则会提交不在步长上的值 */
  step: number
  /** 区间模式下两个值之间至少相隔几个 step */
  minGapSteps?: number
  /** 与刻度的最大距离，绝对值（由调用方按值域比例算好） */
  tolerance: number
}

/**
 * 磁吸：凡是离刻度不超过 `tolerance` 的值，吸到该刻度并按 step 对齐后的位置。
 * 区间模式下吸附后的值必须保持顺序、并与相邻值至少相隔 `minGapSteps` 个 step，
 * 不满足就放弃这个值的吸附（宁可不动，也不要产生倒序或贴合的两个手柄）。
 */
function snapValuesToTicks(
  values: readonly number[],
  options: SnapToTicksOptions,
) {
  const { ticks, min, max, step, minGapSteps = 0, tolerance } = options
  const gap = Math.max(0, minGapSteps) * (Number.isFinite(step) ? step : 0)
  const result = [...values]
  for (let index = 0; index < values.length; index += 1) {
    const current = values[index]
    const nearest = nearestTick(current, ticks)
    if (nearest === undefined) continue
    if (Math.abs(nearest - current) > tolerance) continue
    const aligned = alignToStep(nearest, min, max, step)
    if (aligned === undefined) continue
    const before = result[index - 1]
    const after = result[index + 1]
    if (before !== undefined && aligned < before + gap) continue
    if (after !== undefined && aligned > after - gap) continue
    result[index] = aligned
  }
  return result
}

/** 单值与区间共用的相等判断，用于磁吸前后比较。 */
function sameValue(
  a: number | readonly number[],
  b: number | readonly number[],
) {
  if (typeof a === "number" || typeof b === "number") return a === b
  const left = a as readonly number[]
  const right = b as readonly number[]
  return (
    left.length === right.length &&
    left.every((item, index) => item === right[index])
  )
}

export {
  alignToStep,
  clamp01,
  crossedTick,
  nearestTick,
  resolveTicks,
  rubberBand,
  sameValue,
  snapValuesToTicks,
  stepDecimals,
  toNumberList,
  valueToPercent,
}
export type { SnapToTicksOptions }

"use client"

import * as React from "react"

/**
 * 滑块的音效：用 Web Audio 现场合成，不需要音频文件。
 * 刻度是一声很短的高频「嗒」，音高跟着值走；碰到轨道两端是一声低闷的「咚」。
 * AudioContext 在第一次真正发声（用户手势里）时才创建，满足浏览器的自动播放限制。
 */
let context: AudioContext | null = null

function audio() {
  if (typeof window === "undefined") return null
  if (!context) {
    const Ctor =
      window.AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext
    if (!Ctor) return null
    context = new Ctor()
  }
  if (context.state === "suspended") void context.resume()
  return context
}

const clamp = (value: number) => Math.min(1, Math.max(0, value))

/** 一段指数衰减的正弦：用来做「咚」的主体。 */
function tone(from: number, to: number, duration: number, volume: number) {
  const ctx = audio()
  if (!ctx) return
  const now = ctx.currentTime
  const osc = ctx.createOscillator()
  const gain = ctx.createGain()
  osc.type = "sine"
  osc.frequency.setValueAtTime(from, now)
  osc.frequency.exponentialRampToValueAtTime(to, now + duration)
  gain.gain.setValueAtTime(0.0001, now)
  gain.gain.exponentialRampToValueAtTime(volume, now + 0.005)
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)
  osc.connect(gain).connect(ctx.destination)
  osc.start(now)
  osc.stop(now + duration + 0.02)
}

/** 一段带通滤过的噪声：构成「嗒」的颗粒感，长度只有十几毫秒。 */
function noise(frequency: number, duration: number, volume: number, q = 2.4) {
  const ctx = audio()
  if (!ctx) return
  const now = ctx.currentTime
  const length = Math.max(1, Math.ceil(ctx.sampleRate * duration))
  const buffer = ctx.createBuffer(1, length, ctx.sampleRate)
  const data = buffer.getChannelData(0)
  for (let i = 0; i < length; i++)
    data[i] = (Math.random() * 2 - 1) * (1 - i / length) ** 2
  const source = ctx.createBufferSource()
  source.buffer = buffer
  const filter = ctx.createBiquadFilter()
  filter.type = "bandpass"
  filter.frequency.value = frequency
  filter.Q.value = q
  const gain = ctx.createGain()
  gain.gain.value = volume
  source.connect(filter).connect(gain).connect(ctx.destination)
  source.start(now)
}

/**
 * 一个刻度的滴答声。`pitch` 0–1 表示值在范围里的位置，越高越尖：
 * 高频带通噪声给「嗒」的触感，叠一声极短的正弦给它音高。
 */
function playTick(pitch = 0.5) {
  const t = clamp(pitch)
  noise(2400 + 2600 * t, 0.011, 0.05 + 0.04 * t, 3)
  tone(1100 + 1000 * t, 900 + 800 * t, 0.012, 0.028 + 0.012 * t)
}

/** 碰到轨道两端的一声低闷「咚」：低频下滑 + 一点点噪声让它不空。 */
function playEdge() {
  tone(168, 62, 0.15, 0.17)
  noise(420, 0.045, 0.06, 1.1)
}

/* ---------- 静音偏好：存在 localStorage，全站带音效的组件共用 ---------- */

const STORAGE_KEY = "travinsy:sound:muted"
/** 旧版本用过的键：读到新键没写过时按它迁移，保证升级后偏好不丢。 */
const LEGACY_KEYS = ["isometric-mark:muted"]
const WATCHED_KEYS = [STORAGE_KEY, ...LEGACY_KEYS]
/**
 * 同页广播：`storage` 事件只发给「其他」标签页，本页写 localStorage 不会触发它。
 * 带音效的组件各自有一份静音模块（互不 import），所以约定用同一个事件名互相通知。
 */
const MUTED_EVENT = "travinsy:sound-muted-change"
const listeners = new Set<() => void>()

function readMuted() {
  try {
    const current = window.localStorage.getItem(STORAGE_KEY)
    if (current !== null) return current === "1"
    return LEGACY_KEYS.some((key) => window.localStorage.getItem(key) === "1")
  } catch {
    return false
  }
}

function setMuted(muted: boolean) {
  try {
    window.localStorage.setItem(STORAGE_KEY, muted ? "1" : "0")
  } catch {
    // 隐私模式等存不了时只在本页生效
  }
  listeners.forEach((listener) => listener())
  // 通知同页其他带音效的组件
  window.dispatchEvent(new Event(MUTED_EVENT))
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  const notify = () => listener()
  const onStorage = (event: StorageEvent) => {
    if (event.key === null || WATCHED_KEYS.includes(event.key)) notify()
  }
  window.addEventListener("storage", onStorage)
  window.addEventListener(MUTED_EVENT, notify)
  return () => {
    listeners.delete(listener)
    window.removeEventListener("storage", onStorage)
    window.removeEventListener(MUTED_EVENT, notify)
  }
}

/** 读取 / 切换音效静音。服务端与水合阶段按未静音渲染，挂载后再读本地偏好。 */
function useValueSliderMuted() {
  const muted = React.useSyncExternalStore(subscribe, readMuted, () => false)
  return [muted, setMuted] as const
}

export { playEdge, playTick, useValueSliderMuted }

"use client"

import * as React from "react"
import {
  animate,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type AnimationPlaybackControls,
  type MotionValue,
} from "motion/react"

import { clamp01, rubberBand } from "./utils"

/** 打开 / 关闭过冲的弹簧：`visualDuration` 是回到原位的时间，`bounce` 给它一点回弹。 */
const RECOIL_SPRING = {
  type: "spring",
  visualDuration: 0.4,
  bounce: 0.45,
} as const
/** 轨道在过冲时的最大纵向压缩比例。 */
const SQUASH_RATIO = 0.12

type ElasticSide = "start" | "end"

type UseElasticPullOptions = {
  /** 拖出两端的最大过冲像素，`0` 关闭弹性 */
  elasticity: number
  /** 禁用时立刻收手：移除监听、停止弹簧、过冲归零 */
  disabled?: boolean
  /** 某一侧被拉开时回调，一次手势里每侧只报一次（用来放碰边音效） */
  onEdge?: (side: ElasticSide) => void
}

type ElasticPull = {
  /** 有符号的拉伸像素：负数往左、正数往右 */
  pull: MotionValue<number>
  /** 视觉层的水平位移，和 `scaleX` 配合成「拉住一端」的样子 */
  x: MotionValue<number>
  scaleX: MotionValue<number>
  scaleY: MotionValue<number>
  startIconX: MotionValue<number>
  endIconX: MotionValue<number>
  startIconScale: MotionValue<number>
  endIconScale: MotionValue<number>
  /** 当前拉向哪一端，用于根元素的 `data-overshoot` */
  side: ElasticSide | null
  /** 挂在 `Slider.Control` 上：只量 Control 的矩形，视觉层自己缩放 */
  onPointerDown: (event: React.PointerEvent<HTMLElement>) => void
  /** 键盘在手柄已经位于端点时继续往同方向走，拉一下再弹回来 */
  pulse: (side: ElasticSide) => void
}

/**
 * 橡皮筋过冲：指针拖出轨道后把轨道往那一侧拉长，松手用弹簧收回。
 * 全部走 MotionValue，拖动期间不触发 React 渲染；几何量自始至终只来自 Control 的矩形，
 * 所以缩放视觉层不会影响 Base UI 把指针换算成数值。
 */
function useElasticPull({
  elasticity,
  disabled = false,
  onEdge,
}: UseElasticPullOptions): ElasticPull {
  const reduced = useReducedMotion() ?? false
  const pull = useMotionValue(0)
  // 按下那一刻量到的轨道宽度，只用来把拉伸像素换算成缩放比例
  const width = useMotionValue(1)
  const scaleX = useTransform(
    () => 1 + Math.abs(pull.get()) / Math.max(1, width.get()),
  )
  const scaleY = useTransform(
    () =>
      1 -
      SQUASH_RATIO *
        clamp01(Math.abs(pull.get()) / Math.max(1, elasticity || 1)),
  )
  // 固定以中心为原点，再平移半个拉伸量：视觉上等于拉住一端，换边时不需要切换 transform-origin
  const x = useTransform(pull, (current) => current / 2)
  const startIconX = useTransform(pull, (current) => Math.min(0, current))
  const endIconX = useTransform(pull, (current) => Math.max(0, current))
  const startIconScale = useMotionValue(1)
  const endIconScale = useMotionValue(1)

  const [side, setSide] = React.useState<ElasticSide | null>(null)
  const sideRef = React.useRef<ElasticSide | null>(null)
  // 手势编号：每次按下 / 复位都 +1，弹簧完成时据此判断自己是不是已经被新手势取代
  const gestureRef = React.useRef(0)
  const springRef = React.useRef<AnimationPlaybackControls | null>(null)
  const detachRef = React.useRef<(() => void) | null>(null)
  // 窗口级监听里要读最新属性，用 ref 保存，免得每帧重建监听
  const optionsRef = React.useRef({ elasticity, reduced, onEdge })
  React.useEffect(() => {
    optionsRef.current = { elasticity, reduced, onEdge }
  })

  const setSideSafe = React.useCallback((next: ElasticSide | null) => {
    if (sideRef.current === next) return
    sideRef.current = next
    setSide(next)
  }, [])

  /** 停下正在跑的回弹、过冲归零，并让旧弹簧的完成回调失效。 */
  const reset = React.useCallback(() => {
    gestureRef.current += 1
    springRef.current?.stop()
    springRef.current = null
    pull.set(0)
    setSideSafe(null)
  }, [pull, setSideSafe])

  const recoil = React.useCallback(() => {
    const id = gestureRef.current
    springRef.current?.stop()
    springRef.current = animate(pull, 0, {
      ...RECOIL_SPRING,
      onComplete: () => {
        // 旧手势的弹簧到期时才回来：不许它动新手势的状态
        if (gestureRef.current !== id) return
        springRef.current = null
        setSideSafe(null)
      },
    })
  }, [pull, setSideSafe])

  const nudgeIcon = React.useCallback(
    (target: ElasticSide) => {
      if (reduced) return
      animate(target === "start" ? startIconScale : endIconScale, [1, 1.25, 1], {
        duration: 0.32,
        ease: "easeOut",
      })
    },
    [reduced, startIconScale, endIconScale],
  )

  const onPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      if (disabled || event.button !== 0) return
      // 并发指针（另一根手指还按着）时只保留最新这一组：先把上一组的 window 监听解掉，
      // 否则 detachRef 会被覆盖，旧手势的 move/release 再也解不掉
      detachRef.current?.()
      // 新的手势开始：上一段回弹（上一次拖动或键盘脉冲留下的）立刻作废
      reset()
      const state = optionsRef.current
      if (state.reduced || state.elasticity <= 0) return
      // 用按下这一刻的 Control 矩形量过冲；Control 自己不缩放，之后一直有效
      const rect = event.currentTarget.getBoundingClientRect()
      width.set(Math.max(1, rect.width))
      const pointerId = event.pointerId
      const nudged = { start: false, end: false }

      const detach = () => {
        window.removeEventListener("pointermove", move)
        window.removeEventListener("pointerup", release)
        window.removeEventListener("pointercancel", release)
        window.removeEventListener("lostpointercapture", release)
        window.removeEventListener("blur", release)
        if (detachRef.current === detach) detachRef.current = null
      }
      // 松手、被系统取消、指针捕获丢失、窗口失焦都走这里；重复调用是安全的
      const release = (native: Event) => {
        if ("pointerId" in native) {
          const stale = native as PointerEvent
          if (stale.pointerId !== pointerId) return
        }
        detach()
        if (pull.get() === 0) setSideSafe(null)
        else recoil()
      }
      const move = (native: PointerEvent) => {
        if (native.pointerId !== pointerId) return
        const latest = optionsRef.current
        if (latest.reduced || latest.elasticity <= 0) return
        const beyondEnd = native.clientX - rect.right
        const beyondStart = rect.left - native.clientX
        const next = beyondEnd > 0 ? "end" : beyondStart > 0 ? "start" : null
        if (next === null) {
          setSideSafe(null)
          if (pull.get() !== 0) pull.set(0)
          return
        }
        // 拖动时别选中旁边的文字
        native.preventDefault()
        const stretch = rubberBand(
          Math.max(beyondEnd, beyondStart),
          latest.elasticity,
        )
        pull.set(next === "end" ? stretch : -stretch)
        setSideSafe(next)
        if (!nudged[next]) {
          nudged[next] = true
          nudgeIcon(next)
          latest.onEdge?.(next)
        }
      }

      window.addEventListener("pointermove", move, { passive: false })
      window.addEventListener("pointerup", release)
      window.addEventListener("pointercancel", release)
      window.addEventListener("lostpointercapture", release)
      window.addEventListener("blur", release)
      detachRef.current = detach
    },
    [disabled, reset, width, nudgeIcon, pull, recoil, setSideSafe],
  )

  const pulse = React.useCallback(
    (target: ElasticSide) => {
      if (reduced || elasticity <= 0) return
      reset()
      setSideSafe(target)
      nudgeIcon(target)
      pull.set(target === "end" ? elasticity * 0.4 : elasticity * -0.4)
      recoil()
    },
    [
      reduced,
      elasticity,
      reset,
      setSideSafe,
      nudgeIcon,
      pull,
      recoil,
    ],
  )

  // 拖动途中被禁用：立刻收手，别让 window 监听和回弹继续跑
  React.useEffect(() => {
    if (!disabled) return
    reset()
    detachRef.current?.()
  }, [disabled, reset])

  React.useEffect(
    () => () => {
      gestureRef.current += 1
      springRef.current?.stop()
      detachRef.current?.()
    },
    [],
  )

  return {
    pull,
    x,
    scaleX,
    scaleY,
    startIconX,
    endIconX,
    startIconScale,
    endIconScale,
    side,
    onPointerDown,
    pulse,
  }
}

